1	// Shared vocabulary for the farmhouse + potager. Every part imports from here: the layout constants, the palette
2	// as named constants, the OPENINGS table (single source for every door/window/gate), and one helper per repeated
3	// element. Helpers take the grid (or runParts view) first and place real blocks with correct states.
4	// Coordinates: x east (street runs along x), y up (ground block y=0, walking surface y=1), z south. FRONT = NORTH (-z).
5	import { Grid, B, roof, tree, face, runParts } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
6	export { Grid, B, roof, tree, face, runParts };
7	
8	export const SIZE = [40, 18, 36];
9	
10	// ---- layout (single source; parts and plan.md agree with these) -------------------------------------------------
11	export const HOUSE = { x0: 1, x1: 15, z0: 11, z1: 19, floor1: 1, floor2: 5, eave: 7, ridgeZ: 15 };   // walls y1..y7, roof y8..12 by `mcd roof`
12	export const PORCH = { x0: 16, x1: 18, z0: 12, z1: 18 };                                              // timber lean-to on the garden (east) side
13	export const GARDEN = { x0: 20, x1: 38, z0: 4, z1: 32, cx: 29, cz: 15 };                              // walls on these lines; interior x21..37, z5..31
14	export const BEDS = {                                                                                  // raised beds: rim ring + 4 crop rows
15	  NW: { x0: 22, x1: 27, z0: 6, z1: 13 }, NE: { x0: 31, x1: 36, z0: 6, z1: 13 },
16	  SW: { x0: 22, x1: 27, z0: 17, z1: 24 }, SE: { x0: 31, x1: 36, z0: 17, z1: 24 },
17	};
18	export const GREENHOUSE = { x0: 22, x1: 27, z0: 27, z1: 31 };
19	export const SHED = { x0: 32, x1: 36, z0: 28, z1: 31 };
20	export const COLDFRAME = { x0: 32, x1: 36, z0: 26, z1: 27 };
21	export const WELL = { cx: 29, cz: 15 };
22	
23	// ---- palette constants (all ids are in palette.json) --------------------------------------------------------------
24	export const WALL_MIX = [["cobblestone", 40], ["stone", 25], ["andesite", 20], ["mossy_cobblestone", 15]];   // rough farmhouse stone
25	export const TRIM = "stone_bricks";          // quoins, lintels, jambs, pillars
26	export const PLINTH = "cobblestone";
27	export const BRICK = "bricks";               // chimney, path inlay
28	export const BEAM = "dark_oak_log";          // porch posts and beams
29	export const BOARD = "spruce_planks";        // floors, shed, bed rims
30	export const FLOOR_UP = "oak_planks";
31	export const SHUTTER = "warped";             // shutter trapdoor material (French blue-green)
32	export const ROOF_MATERIAL = "red-tile";     // used by make.sh (mcd roof), listed here for the small library roofs
33	export const LEAF = "oak_leaves", BLOSSOM = "flowering_azalea_leaves";
34	
35	// ---- small utilities ----------------------------------------------------------------------------------------------
36	export const OUT = { north: [0, 0, -1], south: [0, 0, 1], east: [1, 0, 0], west: [-1, 0, 0] };
37	export const opposite = face.opposite;
38	const ALONG = { north: [1, 0, 0], south: [1, 0, 0], east: [0, 0, 1], west: [0, 0, 1] };   // direction a wall runs, given the way it faces
39	export function hash(x, y, z, s = 0) { let h = (x * 374761393 + y * 668265263 + z * 2147483647 + s * 1274126177) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967296; }
40	export function wallBlock(x, y, z) {
41	  const t = WALL_MIX.reduce((a, [, w]) => a + w, 0); let r = hash(x, y, z, 7) * t;
42	  for (const [b, w] of WALL_MIX) { if ((r -= w) < 0) return b; }
43	  return WALL_MIX[0][0];
44	}
45	/** Place a [block, state, nbt] pair from B.* (or a plain block name). */
46	export function put(g, x, y, z, pair, state) {
47	  if (typeof pair === "string") g.set(x, y, z, pair, state); else g.set(x, y, z, pair[0], pair[1], pair[2]);
48	}
49	/** Fill a box with rough wall stone (random per cell, deterministic). */
50	export function stoneFill(g, a, b) {
51	  for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++) for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
52	    for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) g.set(x, y, z, wallBlock(x, y, z));
53	}
54	
55	// ---- OPENINGS: the one table of every door / window / doorway / gate -------------------------------------------------
56	// (x,y,z) = bottom cell of the opening in the wall plane; face = the way it looks out; h = height in cells.
57	// The part that builds a wall calls isOpening() and leaves those cells UNSET; later parts fill them with window()/door().
58	const W = (x, y, z, face, h = 2, extra = {}) => ({ kind: "window", x, y, z, face, h, ...extra });
59	const D = (x, y, z, face, extra = {}) => ({ kind: "door", x, y, z, face, h: 2, ...extra });
60	export const OPENINGS = [
61	  // house front (z=11, north): ground windows y3-4, door at x=8, upper windows y7 (1 high, under the eave)
62	  W(4, 3, 11, "north"), D(8, 2, 11, "north", { mat: "oak" }), W(12, 3, 11, "north"),
63	  W(4, 7, 11, "north", 1), W(8, 7, 11, "north", 1), W(12, 7, 11, "north", 1),
64	  // house back (z=19, south)
65	  W(4, 3, 19, "south"), W(8, 3, 19, "south"), W(12, 3, 19, "south"),
66	  W(4, 7, 19, "south", 1), W(8, 7, 19, "south", 1), W(12, 7, 19, "south", 1),
67	  // west gable (x=1) and east garden wall (x=15, under the porch)
68	  W(1, 3, 15, "west"), W(1, 7, 15, "west", 1),
69	  D(15, 2, 15, "east", { mat: "oak" }), W(15, 3, 13, "east"), W(15, 3, 17, "east"),
70	  // interior doorways in the partition x=9 (no door block, just the gap), ground and upper
71	  { kind: "doorway", x: 9, y: 2, z: 13, face: "east", h: 2 }, { kind: "doorway", x: 9, y: 6, z: 13, face: "east", h: 2 },
72	  // garden gate in the west wall (fence gate at y=1), greenhouse door, shed door
73	  { kind: "gate", x: 20, y: 1, z: 15, face: "west", h: 4 },
74	  D(25, 1, 27, "north", { mat: "oak" }),
75	  D(32, 1, 29, "west", { mat: "spruce" }),
76	];
77	const openCells = new Set();
78	for (const o of OPENINGS) for (let k = 0; k < o.h; k++) openCells.add(`${o.x},${o.y + k},${o.z}`);
79	/** True if (x,y,z) is a cell a wall must leave empty. */
80	export const isOpening = (x, y, z) => openCells.has(`${x},${y},${z}`);
81	
82	/** Trim cells (stone-brick jambs and lintel) around a window/door: [[x,y,z,block,state?]...], placed by the part that owns the wall. */
83	export function frameCells(o) {
84	  const a = ALONG[o.face], out = [];
85	  if (o.kind === "doorway" || o.kind === "gate") return out;
86	  for (let k = 0; k < o.h; k++) for (const s of [-1, 1]) out.push([o.x + a[0] * s, o.y + k, o.z + a[2] * s, TRIM]);
87	  for (const s of [-1, 0, 1]) out.push([o.x + a[0] * s, o.y + o.h, o.z + a[2] * s, TRIM]);
88	  return out;
89	}
90	
91	// ---- windows, doors, gate ------------------------------------------------------------------------------------------
92	/** Glass panes in the opening (connected along the wall), open shutters either side outside, a stone-brick sill under it. */
93	export function window(g, { x, y, z, face: f, h = 2, shutters = true, sill = true }) {
94	  const a = ALONG[f], o = OUT[f];
95	  const along = f === "north" || f === "south" ? { east: "true", west: "true", north: "false", south: "false" } : { north: "true", south: "true", east: "false", west: "false" };
96	  for (let k = 0; k < h; k++) g.set(x, y + k, z, "glass_pane", along);
97	  if (shutters) for (const s of [-1, 1]) for (let k = 0; k < h; k++)
98	    g.set(x + a[0] * s + o[0], y + k, z + a[2] * s + o[2], ...B.trapdoor(SHUTTER, opposite(f), "bottom", true));
99	  if (sill) g.set(x + o[0], y - 1, z + o[2], ...B.slab("stone_brick", "top"));
100	}
101	/** A plank door (lower+upper) in the opening, closed, hinge left. face = the way it looks out. */
102	export function door(g, { x, y, z, face: f, mat = "oak" }) {
103	  g.set(x, y, z, ...B.door(mat, f, "lower", "left"));
104	  g.set(x, y + 1, z, ...B.door(mat, f, "upper", "left"));
105	}
106	/** Garden gate: an oak fence gate in the opening, closed. face = the way it looks out. */
107	export function gate(g, { x, y, z, face: f }) {
108	  g.set(x, y, z, "oak_fence_gate", { facing: f, open: "false", in_wall: "false" });
109	}
110	
111	// ---- furniture ----------------------------------------------------------------------------------------------------
112	/** A table: fence leg + pressure plate on top (tabletop at y+1). Place one per cell of the table. */
113	export function table(g, x, y, z) { g.set(x, y, z, ...B.fence("oak")); g.set(x, y + 1, z, "oak_pressure_plate", { powered: "false" }); }
114	/** A chair of stairs; `sitterFaces` = the way the person looks (toward the table); the stair back is behind them. */
115	export function chair(g, x, y, z, sitterFaces, mat = "oak") { g.set(x, y, z, ...B.stairs(mat, opposite(sitterFaces))); }
116	/** A bed: foot at (x,y,z), head one cell on in `facing` (the way the head end lies). color: red|white|blue. */
117	export function bed(g, x, y, z, facing, color = "red") {
118	  const o = OUT[facing];
119	  g.set(x, y, z, `${color}_bed`, { facing, part: "foot" });
120	  g.set(x + o[0], y, z + o[2], `${color}_bed`, { facing, part: "head" });
121	}
122	export const barrel = (g, x, y, z, facing = "up") => g.set(x, y, z, "barrel", { facing, open: "false" });
123	export const chest = (g, x, y, z, facing = "north") => g.set(x, y, z, "chest", { facing, type: "single", waterlogged: "false" });
124	/** A lit campfire hearth cell (put it in a brick niche under the chimney). */
125	export const hearth = (g, x, y, z, facing = "east") => g.set(x, y, z, "campfire", { facing, lit: "true", signal_fire: "false", waterlogged: "false" });
126	export const furnace = (g, x, y, z, facing = "north", kind = "furnace") => g.set(x, y, z, kind, { facing, lit: "false" });
127	export const bookshelf = (g, x, y, z) => g.set(x, y, z, "bookshelf");
128	export const waterCauldron = (g, x, y, z) => g.set(x, y, z, "water_cauldron", { level: "3" });
129	export const pot = (g, x, y, z, plant = "potted_poppy") => g.set(x, y, z, plant);
130	/** A lantern standing on a block (hanging=false) or hanging from the block above (hanging=true). */
131	export const lantern = (g, x, y, z, hanging = false) => g.set(x, y, z, ...B.lantern(hanging));
132	/** A lamp post: fence posts h high with a lantern on top (lantern at y+h). */
133	export function lamp(g, x, y, z, h = 3, mat = "dark_oak") {
134	  for (let k = 0; k < h; k++) g.set(x, y + k, z, ...B.fence(mat));
135	  g.set(x, y + h, z, ...B.lantern(false));
136	}
137	/** A straight run of fence/wall posts from (x0,z0) to (x1,z1) at height y (one axis only); skip = [[x,z]...] gaps. Connections are fixed by fixConnections(). */
138	export function fenceRun(g, x0, z0, x1, z1, y, mat = "oak", { skip = [], wall = false } = {}) {
139	  for (let x = Math.min(x0, x1); x <= Math.max(x0, x1); x++) for (let z = Math.min(z0, z1); z <= Math.max(z0, z1); z++) {
140	    if (skip.some(([sx, sz]) => sx === x && sz === z)) continue;
141	    g.set(x, y, z, ...(wall ? B.wall(mat) : B.fence(mat)));
142	  }
143	}
144	
145	// ---- the garden ---------------------------------------------------------------------------------------------------
146	const MAXAGE = { wheat: 7, carrots: 7, potatoes: 7, beetroots: 3 };
147	/** One crop block at age (clamped to the crop's max) on whatever is below; the farmland under it must be placed by the caller. */
148	export function crop(g, x, y, z, kind, age = 99) { g.set(x, y, z, kind, { age: String(Math.min(age, MAXAGE[kind])) }); }
149	/**
150	 * A raised bed: timber rim (planks at y, a bottom slab on top at y+1), farmland inside at y, crops at y+1.
151	 * rows = crop kinds in order of increasing x (axis "z": rows run along z) or increasing z (axis "x");
152	 * water = [[x,z],...] source cells inside the bed (at y, in place of farmland: hydrates farmland within 4 blocks);
153	 * ripeness: "ripe" | "mixed" (age by position) | "young".
154	 */
155	export function plantedBed(g, { x0, z0, x1, z1, rows, axis = "z", water = [], ripeness = "mixed", y = 1, rim = "spruce" }) {
156	  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
157	    const edge = x === x0 || x === x1 || z === z0 || z === z1;
158	    if (edge) { g.set(x, y, z, `${rim}_planks`); g.set(x, y + 1, z, ...B.slab(rim, "bottom")); continue; }
159	    if (water.some(([wx, wz]) => wx === x && wz === z)) { g.set(x, y, z, "water", { level: "0" }); continue; }
160	    g.set(x, y, z, "farmland", { moisture: "7" });
161	    const i = axis === "z" ? x - x0 - 1 : z - z0 - 1, kind = rows[i % rows.length], pos = axis === "z" ? z : x;
162	    const age = ripeness === "ripe" ? 99 : ripeness === "young" ? 2 : 3 + ((pos + i) % 5);
163	    crop(g, x, y + 1, z, kind, age);
164	  }
165	}
166	/** A trained fruit tree (espalier) flat against a wall: log spine, limb logs, a leaf fan 5 wide x 4 tall. (x,z) = spine cell NEXT TO the wall; wall = which side the wall is on. */
167	export function espalier(g, { x, z, wall, y = 1, leaf = LEAF }) {
168	  const a = wall === "west" || wall === "east" ? [0, 0, 1] : [1, 0, 0], axis = a[0] ? "x" : "z";
169	  const at = (o, yy) => [x + a[0] * o, y + yy, z + a[2] * o];
170	  g.set(x, y - 1, z, "coarse_dirt");
171	  g.set(...at(0, 0), ...B.log("oak", "y")); g.set(...at(0, 1), ...B.log("oak", "y")); g.set(...at(0, 2), ...B.log("oak", "y"));
172	  for (const o of [-1, 1]) { g.set(...at(o, 1), leaf); g.set(...at(o, 2), ...B.log("oak", axis)); }
173	  for (const o of [-2, 2]) g.set(...at(o, 2), leaf);
174	  for (const o of [-2, -1, 0, 1, 2]) g.set(...at(o, 3), leaf);
175	}
176	/** A rose/bean arch across a path: two fence posts, a fence bar over the path, flowering leaves and rose bushes. Spans z=zA..zB at column x (path runs along x). */
177	export function roseArch(g, { x, zA, zB, y = 1 }) {
178	  for (const z of [zA, zB]) {
179	    for (let k = 0; k < 3; k++) g.set(x, y + k, z, ...B.fence("spruce"));
180	    for (const dx of [-1, 1]) {
181	      g.set(x + dx, y - 1, z, "coarse_dirt");
182	      g.set(x + dx, y, z, "rose_bush", { half: "lower" }); g.set(x + dx, y + 1, z, "rose_bush", { half: "upper" });
183	      g.set(x + dx, y + 2, z, BLOSSOM);
184	    }
185	    g.set(x, y + 3, z, BLOSSOM);
186	  }
187	  for (let z = zA; z <= zB; z++) { g.set(x, y + 3, z, ...B.fence("spruce")); g.set(x, y + 4, z, BLOSSOM); }
188	}
189	/** The well: 3x3 stone-brick ring around a water source, four dark-oak posts, a crossbeam with a chain and bucket, a pyramid roof. */
190	export function well(g, { cx, cz, y = 1 }) {
191	  for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) {
192	    if (!dx && !dz) { g.set(cx, y, cz, "water", { level: "0" }); continue; }
193	    g.set(cx + dx, y, cz + dz, dx && dz ? "mossy_stone_bricks" : "stone_bricks");
194	  }
195	  for (const dx of [-1, 1]) for (const dz of [-1, 1]) for (let k = 1; k <= 3; k++) g.set(cx + dx, y + k, cz + dz, ...B.log("dark_oak", "y"));
196	  for (const dx of [-1, 0, 1]) g.set(cx + dx, y + 3, cz, ...B.log("spruce", "x"));
197	  g.set(cx, y + 2, cz, ...B.chain("y")); g.set(cx, y + 1, cz, "cauldron");
198	  roof(g, [[cx - 1, cz - 1, cx + 1, cz + 1]], "pyramid", { y: y + 4, material: "spruce", overhang: 1 });
199	}
200	/** A sundial: stone-brick wall pedestal, smooth-stone dial, lightning-rod gnomon. */
201	export function sundial(g, { x, z, y = 1 }) {
202	  g.set(x, y, z, ...B.wall("stone_brick")); g.set(x, y + 1, z, ...B.wall("stone_brick"));
203	  g.set(x, y + 2, z, ...B.slab("smooth_stone", "bottom")); g.set(x, y + 3, z, "lightning_rod", { facing: "up", powered: "false" });
204	}
205	/** A garden urn on a pedestal. */
206	export function urn(g, { x, z, y = 1 }) {
207	  g.set(x, y, z, ...B.wall("stone_brick")); g.set(x, y + 1, z, "stone_bricks"); g.set(x, y + 2, z, "decorated_pot");
208	}
209	
210	// ---- small buildings ----------------------------------------------------------------------------------------------
211	/** Glasshouse: stone-brick plinth, glass walls between birch corner posts, a stepped glass gable roof (ridge along x), birch-slab ridge. Door gap comes from OPENINGS. */
212	export function greenhouse(g, { x0, z0, x1, z1, y = 1 }) {
213	  const zm = Math.floor((z0 + z1) / 2);
214	  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
215	    if (!(x === x0 || x === x1 || z === z0 || z === z1)) continue;
216	    const post = (x === x0 || x === x1) && (z === z0 || z === z1);
217	    for (let k = 0; k <= 2; k++) {
218	      if (isOpening(x, y + k, z)) continue;
219	      if (post) g.set(x, y + k, z, ...B.log("birch", "y"));
220	      else g.set(x, y + k, z, k === 0 ? "stone_bricks" : "glass");
221	    }
222	  }
223	  // roof: eaves at y+3 (z0 and z1 rows), one step in per course up to the ridge row zm
224	  for (let s = 0; z0 + s <= zm; s++) {
225	    const za = z0 + s, zb = z1 - s;
226	    for (let x = x0; x <= x1; x++) {
227	      const end = x === x0 || x === x1;
228	      g.set(x, y + 3 + s, za, end ? "birch_planks" : "glass"); g.set(x, y + 3 + s, zb, end ? "birch_planks" : "glass");
229	    }
230	    if (s > 0) for (let z = za; z <= zb; z++) { g.set(x0, y + 3 + s - 1, z, "glass"); g.set(x1, y + 3 + s - 1, z, "glass"); }
231	  }
232	  for (let x = x0; x <= x1; x++) g.set(x, y + 3 + (zm - z0) + 1, zm, ...B.slab("birch", "bottom"));
233	}
234	/** Cold frame: spruce-plank ring (1 high), glass-pane ring on it, farmland with seedling carrots inside. */
235	export function coldFrame(g, { x0, z0, x1, z1, y = 1 }) {
236	  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
237	    const edge = x === x0 || x === x1 || z === z0 || z === z1;
238	    if (edge) { g.set(x, y, z, "spruce_planks"); g.set(x, y + 1, z, "glass_pane", { north: "false", south: "false", east: "false", west: "false" }); }
239	    else { g.set(x, y, z, "farmland", { moisture: "7" }); crop(g, x, y + 1, z, "carrots", 1 + ((x + z) % 3)); }
240	  }
241	}
242	/** Tool shed: plank walls with spruce-log corners (y..y+2), gabled spruce roof by roof(); door gap from OPENINGS. */
243	export function toolShed(g, { x0, z0, x1, z1, y = 1 }) {
244	  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
245	    if (!(x === x0 || x === x1 || z === z0 || z === z1)) continue;
246	    const post = (x === x0 || x === x1) && (z === z0 || z === z1);
247	    for (let k = 0; k <= 2; k++) { if (isOpening(x, y + k, z)) continue; if (post) g.set(x, y + k, z, ...B.log("spruce", "y")); else g.set(x, y + k, z, "spruce_planks"); }
248	  }
249	  roof(g, [[x0, z0, x1, z1]], "gable", { y: y + 3, material: "dark_oak", overhang: 1 });
250	}
251	
252	// ---- post-pass: connect fences, walls, panes and bars to their neighbours (the renderer draws states literally) -----
253	const NOT_FULL = /(stairs|slab|lantern|banner|torch|chain|trapdoor|campfire|rod|sign|door|carpet|plate|pot|bush|tulip|allium|poppy|daisy|cornflower|dandelion|lilac|peony|wheat|carrots|potatoes|beetroots|_bed$|vine|water|cauldron|leaves|fern|grass$|farmland)/;
254	/** Call once on the raw grid after runParts. Returns how many blocks were re-set. */
255	export function fixConnections(g) {
256	  const D4 = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] };
257	  const full = (x, y, z) => { const b = g.blockAt(x, y, z).replace("minecraft:", ""); return b !== "air" && !NOT_FULL.test(b) && !/(_fence|_wall|_pane|iron_bars)$/.test(b); };
258	  let n = 0;
259	  for (const c of [...g.cells.values()]) {
260	    const b = c.block.replace("minecraft:", ""), [x, y, z] = c.pos;
261	    const isFence = /_fence$/.test(b), isWall = /_wall$/.test(b), isPane = /(glass_pane|iron_bars)$/.test(b);
262	    if (!isFence && !isWall && !isPane) continue;
263	    const st = {};
264	    for (const [d, [dx, dz]] of Object.entries(D4)) {
265	      const nb = g.blockAt(x + dx, y, z + dz).replace("minecraft:", "");
266	      const same = isFence ? /_fence$|_fence_gate$/.test(nb) : isWall ? /_wall$/.test(nb) : /(glass_pane|iron_bars)$/.test(nb);
267	      const solid = full(x + dx, y, z + dz);
268	      st[d] = isWall ? (same || solid ? "low" : "none") : String(same || solid);
269	    }
270	    if (isWall) { const k = Object.values(st).filter((v) => v !== "none").length; st.up = String(!(k === 2 && ((st.north !== "none" && st.south !== "none") || (st.east !== "none" && st.west !== "none"))) || !g.isAir(x, y + 1, z)); }
271	    st.waterlogged = "false";
272	    g.set(x, y, z, c.block, st, c.nbt); n++;
273	  }
274	  return n;
275	}
